import {experiments,sample,sketch} from './engine.js';
const $=s=>document.querySelector(s);
let saved={};try{saved=JSON.parse(localStorage.getItem('atl-state')||'{}')||{}}catch{}
let current=experiments.findIndex(x=>x.id===saved.experiment);if(current<0)current=0;
let board=saved.board==='teensy'?'teensy':'uno',values=experiments.map(e=>e.value),completed=Array.isArray(saved.completed)?saved.completed.filter(x=>experiments.some(e=>e.id===x)):[],running=false,timer=null,start=0,page='workspace',lastLog=-1;
if(Array.isArray(saved.values))values=experiments.map((e,i)=>Number.isFinite(saved.values[i])?Math.min(e.max,Math.max(e.min,saved.values[i])):e.value);
function persist(){try{localStorage.setItem('atl-state',JSON.stringify({experiment:experiments[current].id,board,values,completed}));}catch{toast('Browser storage is unavailable; this session still works.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function stop(){running=false;clearInterval(timer);timer=null;if($('#run')){$('#run').textContent='▶ Start simulation';$('#sim-status').innerHTML='<i></i> Ready';}}
function esc(s){return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}
function circuit(){const analog=current===2,pwm=current===1;return `<div class="circuit-label">VIRTUAL CIRCUIT · ${analog?'ANALOG INPUT':pwm?'PWM OUTPUT':'DIGITAL OUTPUT'}</div><svg viewBox="0 0 600 300" role="img" aria-label="${analog?'Potentiometer connected to A0, supply and ground':pwm?'Pin 9 connected through a 330 ohm resistor to an LED and ground':'Board with integrated pin 13 LED'}"><defs><pattern id="pins" width="15" height="12" patternUnits="userSpaceOnUse"><rect x="3" y="3" width="7" height="6" rx="1" fill="#b6b5a0"/></pattern><filter id="glow"><feGaussianBlur stdDeviation="5"/></filter></defs><ellipse cx="260" cy="255" rx="157" ry="10" fill="#dde4dc" opacity=".5"/><rect x="105" y="67" width="273" height="178" rx="13" fill="${board==='uno'?'#238c87':'#26725d'}" stroke="#1b6967" stroke-width="3"/><circle cx="119" cy="81" r="5" fill="#d2decf"/><circle cx="363" cy="231" r="5" fill="#d2decf"/><rect x="156" y="71" width="204" height="16" rx="2" fill="#244746"/><rect x="161" y="73" width="195" height="12" fill="url(#pins)"/><rect x="156" y="223" width="204" height="16" rx="2" fill="#244746"/><rect x="161" y="225" width="195" height="12" fill="url(#pins)"/><rect x="87" y="100" width="57" height="43" rx="3" fill="#b9c8c7" stroke="#8da4a2" stroke-width="2"/><rect x="87" y="108" width="14" height="27" fill="#6a8585"/><rect x="101" y="194" width="43" height="29" rx="3" fill="#264341"/><rect x="217" y="157" width="116" height="35" rx="3" fill="#214744"/><path d="M221 151h108 M221 198h108" stroke="#b6bba6" stroke-width="5" stroke-dasharray="4 5"/><rect x="157" y="160" width="21" height="30" rx="3" fill="#b1c6bb"/><circle cx="160" cy="118" r="6" fill="#e8e1bb"/><text x="213" y="121" fill="#e0f2e8" font-family="Arial" font-size="35">∞</text><text x="273" y="115" fill="#e3f4e9" font-family="Arial" font-size="13" font-weight="bold">${board==='uno'?'UNO':'TEENSY'}</text><text x="273" y="131" fill="#cae8db" font-family="monospace" font-size="8">${board==='uno'?'ARDUINO':'4.1 · 3.3 V'}</text><text x="175" y="99" fill="#d7ece0" font-family="monospace" font-size="7">13 12 11 10 9 8 7 6 5 4 3 2</text><text x="182" y="217" fill="#d7ece0" font-family="monospace" font-size="7">GND   ${board==='uno'?'5V':'3V3'}        A0 A1 A2 A3</text><circle id="onboard-led" cx="186" cy="117" r="5" fill="#5f8057"/><text x="181" y="135" font-size="7" fill="#c7e6d8">L</text>${analog?`<path d="M290 230V267H469V166" fill="none" stroke="#d3aa5d" stroke-width="3"/><path d="M220 230V278H489V165" fill="none" stroke="#ce715c" stroke-width="3"/><path d="M190 230V286H449V165" fill="none" stroke="#667d78" stroke-width="3"/><rect x="436" y="122" width="66" height="51" rx="7" fill="#688b8a"/><circle cx="469" cy="139" r="26" fill="#dce5df" stroke="#8da49a" stroke-width="3"/><line id="knob" x1="469" y1="139" x2="469" y2="119" stroke="#365a50" stroke-width="4"/><text x="424" y="98" font-size="10" fill="#7b8c81">10 kΩ potentiometer</text>`:pwm?`<path d="M235 79V46H469V93" fill="none" stroke="#d4aa61" stroke-width="3"/><rect x="464" y="91" width="11" height="36" rx="3" fill="#d9c39b" stroke="#b49a73"/><path d="M464 99h11m-11 8h11m-11 10h11" stroke="#a66d49" stroke-width="3"/><text x="486" y="114" fill="#8f9884" font-size="9">330 Ω</text><path d="M469 127v38m0 32v63H190v-30" fill="none" stroke="#64877c" stroke-width="3"/><circle id="led-glow" cx="469" cy="178" r="22" fill="#b5d768" opacity="0" filter="url(#glow)"/><path id="external-led" d="M458 190v-14a11 11 0 0 1 22 0v14z" fill="#a1b88a" stroke="#7e9b68" stroke-width="2"/><text x="441" y="218" fill="#85977f" font-size="10">LED</text>`:`<path d="M186 112V40H435" fill="none" stroke="#98b5a1" stroke-width="1" stroke-dasharray="4 4"/><text x="398" y="32" fill="#6d8a77" font-size="11">Built-in LED · pin 13</text><rect x="417" y="116" width="103" height="66" rx="8" fill="#fff" stroke="#dbe5d9"/><text x="430" y="138" fill="#91a18e" font-size="9">DIGITAL STATE</text><text id="state-text" x="430" y="163" fill="#537b5a" font-family="monospace" font-size="18">LOW</text>`}</svg><div class="circuit-note">Illustrative wiring · not a physical board emulator</div>`}
function render(){stop();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').textContent=page==='workspace'?experiments[current].name:({lessons:'Learning path',reference:'Board reference',guide:'Getting started'})[page];
 if(page==='workspace')workspace();else if(page==='lessons')lessons();else if(page==='reference')reference();else guide();}
function workspace(){const e=experiments[current];$('#main').innerHTML=`<div class="heading"><div><div class="eyebrow">EXPERIMENT. UNDERSTAND. BUILD.</div><h1>Make your ideas light up.</h1><p>A little code. A simple circuit. A new possibility.</p></div><span class="badge">◉ &nbsp; No hardware needed</span></div><div class="experiment-strip">${experiments.map((x,i)=>`<button class="experiment ${i===current?'selected':''}" data-experiment="${i}"><span class="num">0${i+1}</span><span><strong>${x.name} ${completed.includes(x.id)?'✓':''}</strong><small>${x.category} · ${x.duration}</small></span></button>`).join('')}</div><div class="workgrid"><section class="panel"><div class="panel-head"><span>◈ &nbsp; Circuit playground</span><span id="sim-status" class="status"><i></i> Ready</span></div><div class="circuit">${circuit()}</div><div class="board-settings"><span>DEVELOPMENT BOARD</span><select id="board" aria-label="Development board"><option value="uno" ${board==='uno'?'selected':''}>Arduino Uno R3 · 5 V</option><option value="teensy" ${board==='teensy'?'selected':''}>Teensy 4.1 · 3.3 V</option></select></div><div class="runbar"><button id="run" class="primary">▶ Start simulation</button><button id="reset" class="subtle">↻ Reset</button><span class="hint">Try it. Change it. See what happens.</span></div></section><section class="panel"><div class="panel-head code-head"><span>⌘ &nbsp; ${e.id}.ino</span><button id="copy" class="subtle">Copy code</button></div><pre id="code" class="code"></pre><div class="parameters"><div class="parameter-row"><label for="parameter">${e.label}</label><output id="param-out">${values[current]} ${e.unit}</output></div><input id="parameter" type="range" min="${e.min}" max="${e.max}" step="${e.step}" value="${values[current]}"><div class="parameter-help">${current===2?'Move the virtual input; the sketch reads A0.':'Adjust to update the sketch and live simulation.'}</div></div></section></div><div class="lower"><section class="panel"><div class="panel-head"><span>›_ &nbsp; Simulation monitor <small> &nbsp; ${current===2?'9600 baud sketch':'virtual output trace'}</small></span><button id="clear" class="linkbutton">Clear</button></div><div id="monitor" class="monitor" role="log" aria-label="Simulation monitor"><div class="quiet">Ready when you are. Start the simulation to see output.</div></div></section><section class="panel"><div class="panel-head"><span>↗ &nbsp; Inside this experiment</span><small>LESSON 0${current+1}</small></div><div class="lesson-content"><strong>${e.name}</strong><p>${e.learn}</p><div class="lesson-action"><span style="font-size:10px;color:#8c9b91">◷ ${e.duration} · Beginner</span><button id="learn" class="linkbutton">Explore the lesson →</button></div></div></section></div><div class="tip"><span>✧</span><span><strong>A little insight</strong> &nbsp; ${current===0?'The onboard LED already has a resistor. No external wiring is needed for this experiment.':current===1?'An external LED needs a current-limiting resistor. This example uses 330 Ω.':'Teensy 4.1 inputs are not 5 V tolerant. Power this potentiometer from 3.3 V.'}</span></div>`;
 $('#code').textContent=sketch(e.id,values[current],board);
 document.querySelectorAll('[data-experiment]').forEach(b=>b.onclick=()=>{current=+b.dataset.experiment;persist();render()});
 $('#board').onchange=ev=>{board=ev.target.value;persist();render()};$('#run').onclick=()=>{if(running){stop();return}running=true;start=performance.now();lastLog=-1;$('#run').textContent='■ Stop simulation';$('#sim-status').innerHTML='<i></i> Running';$('#monitor').innerHTML='';tick();timer=setInterval(tick,50)};
 $('#parameter').oninput=ev=>{values[current]=+ev.target.value;$('#param-out').textContent=`${values[current]} ${e.unit}`;$('#code').textContent=sketch(e.id,values[current],board);persist();if(running)tick()};
 $('#reset').onclick=()=>{values[current]=e.value;persist();render();toast('Experiment reset')};$('#clear').onclick=()=>$('#monitor').innerHTML='';$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(sketch(e.id,values[current],board));toast('Sketch copied')}catch{toast('Clipboard unavailable. Use Export sketch instead.')}};$('#learn').onclick=()=>{page='lessons';render();document.getElementById('lesson-'+current).scrollIntoView({behavior:'smooth',block:'center'})};}
function tick(){const elapsed=performance.now()-start,e=experiments[current],s=sample(e.id,values[current],elapsed,board==='uno'?5:3.3);if($('#onboard-led'))$('#onboard-led').setAttribute('fill',current===0&&s.high?'#e9ff83':'#5f8057');if($('#state-text'))$('#state-text').textContent=s.high?'HIGH':'LOW';if($('#external-led')){$('#external-led').setAttribute('fill',`hsl(77 65% ${30+s.brightness*40}%)`);$('#led-glow').setAttribute('opacity',s.brightness)}if($('#knob'))$('#knob').setAttribute('transform',`rotate(${values[current]*2.7-135} 469 139)`);
 const bucket=Math.floor(elapsed/(current===0?values[current]:current===2?100:500));if(bucket!==lastLog){lastLog=bucket;const line=document.createElement('div');line.textContent=`${(elapsed/1000).toFixed(2).padStart(6,'0')} s  →  ${current===0?'pin 13 = '+(s.high?'HIGH':'LOW'):current===1?'pin 9 · duty '+s.reading+'%':'A0 = '+s.reading+'  ('+s.voltage.toFixed(2)+' V)'}`;$('#monitor').append(line);while($('#monitor').children.length>80)$('#monitor').firstChild.remove();$('#monitor').scrollTop=$('#monitor').scrollHeight}}
function lessons(){$('#main').innerHTML=`<div class="heading"><div><div class="eyebrow">ONE EXPERIMENT AT A TIME</div><h1>Your learning path</h1><p>Understand the idea, try it in the lab, and check what you learned.</p></div><span class="badge">${completed.length} / 3 completed</span></div><div class="progress-track"><div style="width:${completed.length/3*100}%"></div></div><div class="cards">${experiments.map((e,i)=>`<section id="lesson-${i}" class="panel card"><div class="eyebrow">0${i+1} · ${e.category}</div><h2>${e.name}</h2><p>${e.description}</p><p>${e.learn}</p><button class="primary" data-open="${i}">Open experiment →</button><div class="quiz"><strong>${e.question}</strong><div>${e.answers.map((a,j)=>`<button data-answer="${i},${j}">${a}</button>`).join('')}</div><p class="quiz-result" id="result-${i}" role="status">${completed.includes(e.id)?'✓ Completed. '+e.explanation:'Choose an answer to check your understanding.'}</p></div></section>`).join('')}</div><div class="tip">Progress is stored in this browser. Answer a knowledge check correctly to complete its lesson.</div>`;
 document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{current=+b.dataset.open;page='workspace';persist();render()});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const[i,j]=b.dataset.answer.split(',').map(Number),e=experiments[i];if(j===e.correct){if(!completed.includes(e.id))completed.push(e.id);persist();$('#result-'+i).textContent='✓ Correct! '+e.explanation;$('.badge').textContent=`${completed.length} / 3 completed`;$('.progress-track div').style.width=completed.length/3*100+'%'}else $('#result-'+i).textContent='Not quite. '+e.explanation});}
function reference(){$('#main').innerHTML=`<div class="heading"><div><div class="eyebrow">KNOW YOUR HARDWARE</div><h1>Two boards. Many possibilities.</h1><p>The key differences for the experiments in this lab.</p></div></div><section class="panel"><table><thead><tr><th>Feature</th><th>Arduino Uno R3</th><th>Teensy 4.1</th></tr></thead><tbody><tr><td>Logic level</td><td>5 V</td><td>3.3 V · inputs are not 5 V tolerant</td></tr><tr><td>Built-in LED</td><td>Pin 13</td><td>Pin 13</td></tr><tr><td>PWM experiment</td><td>Pin 9, 8-bit (0–255)</td><td>Pin 9, explicitly set to 8-bit</td></tr><tr><td>Analog experiment</td><td>A0, 10-bit (0–1023)</td><td>A0, explicitly set to 10-bit</td></tr><tr><td>Potentiometer wiring</td><td>Outer pins: 5 V and GND; wiper: A0</td><td>Outer pins: 3.3 V and GND; wiper: A0</td></tr></tbody></table></section><div class="tip"><strong>Before connecting real hardware:</strong> Disconnect power before rewiring. This simulator does not model current, shorts, loading, ADC noise, or exact timing.</div><section class="panel article" style="margin-top:22px"><h2>From simulation to a real board</h2><p>Export a sketch, open the .ino file in Arduino IDE, select the matching board and port, then upload. Teensy requires its board support package. The visual board is illustrative: always verify the physical pin labels.</p><p><a href="https://docs.arduino.cc/hardware/uno-rev3/" target="_blank" rel="noopener">Arduino Uno official documentation ↗</a> &nbsp; <a href="https://www.pjrc.com/store/teensy41.html" target="_blank" rel="noopener">Teensy 4.1 official documentation ↗</a></p></section>`}
function guide(){$('#main').innerHTML=`<div class="heading"><div><div class="eyebrow">A FRIENDLY START</div><h1>Your workbench, explained.</h1><p>Start experimenting now. Learn how the web application works when you’re ready.</p></div></div><section class="panel article"><h2>1. Run your first experiment</h2><p>Open Lab workspace and choose Blink an LED. Press Start simulation. Change the blink interval and watch both the LED and output trace. The slider generates a matching Arduino sketch.</p><h2>2. Understand what is simulated</h2><p>The app calculates digital timing, PWM duty cycle, and an ideal 10-bit ADC reading. It does not compile C++, run an MCU emulator, or connect to USB hardware. Code is generated from the controls, not typed into an unrestricted editor. The blink and PWM monitors show a virtual trace; the analog sketch uses Serial.println.</p><h2>3. Run the source on Windows</h2><p><a href="https://github.com/NEW-WAY-2023/ArduTeensy" target="_blank" rel="noopener">Open source + Windows guide on GitHub ↗</a></p><p>With the project source folder on your computer, install Python 3 from python.org and enable “Add python.exe to PATH”. Open PowerShell in the project folder (right-click an empty area in File Explorer and choose “Open in Terminal”). Run:</p><pre>py -m http.server 8000 --directory dist</pre><p>Open <code>http://localhost:8000</code> in your browser. Keep the terminal open. Press Ctrl+C to stop the server. Use a local server instead of double-clicking index.html because JavaScript modules need HTTP.</p><h2>4. Find your way around the files</h2><ul><li><code>dist/index.html</code> creates the page shell and navigation.</li><li><code>dist/styles.css</code> controls layout, colors, and mobile sizing.</li><li><code>dist/app.js</code> handles buttons, screens, animation, and saved progress.</li><li><code>dist/engine.js</code> contains the simulation math and sketch generator.</li><li><code>tests/engine.test.mjs</code> checks timing, PWM, ADC conversion, and sketch output.</li><li><code>README.md</code> explains Windows setup, testing, Git, and deployment.</li></ul><h2>5. Save your work with Git</h2><p>Git records snapshots of source files. GitHub is a separate website that can store a copy of your repository. Neither is required to use this app. The README includes exact commands for a new local copy.</p><h2>6. Data and privacy</h2><p>Your selected board, slider settings, and completed lessons are saved only in this browser’s local storage. They do not sync between devices and can be lost if browser data is cleared. No account or database is needed for these features.</p></section>`}
$('nav').onclick=e=>{const b=e.target.closest('[data-page]');if(b){page=b.dataset.page;render()}};$('.brand').onclick=e=>{e.preventDefault();page='workspace';render()};$('#export').onclick=()=>{const e=experiments[current],url=URL.createObjectURL(new Blob([sketch(e.id,values[current],board)],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download=e.id+'.ino';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(e.id+'.ino exported')};render();
